    $backupBase=$root.'/storage/app/saas_list_ui_backups';
    $checksum=static fn(string $file):string=>hash_file('sha256',$file);
    $resolve=static function(string $relative)use($root):string {
        if($relative===''||str_contains($relative,'\\')||str_starts_with($relative,'/')||preg_match('~(^|/)\.\.?(/|$)~',$relative)||!preg_match('~^(app|resources/views)/[A-Za-z0-9_./-]+$~',$relative))throw new RuntimeException('Unsafe path: '.$relative);
